/* ===== Writer P — family arc: each partner's yes / vow / baby / home / moment ===== */
/* yes, vow, baby, home: self-contained narrated lines (speaker named, quotes included).
   home is a getter: it uses S.flags.child.name when there is a child, otherwise a couple-only picture. */
const f2_M=id=>t('婚后','Married life','Vida de casados')+' · '+NM(id);
const f2_kid=()=>S.flags&&S.flags.child&&S.flags.child.name?S.flags.child.name:null;
const f2_home=(id,withKid,alone)=>Object.defineProperty(PARTNER[id],'home',{get(){const k=f2_kid();return k?withKid(k):alone},set(v){},enumerable:true,configurable:true});

/* ---------- LUCÍA ---------- */
Object.assign(PARTNER.lucia,{
 yes:t(`露西娅盯着戒指看了很久，又是那种估价的眼神：“城里人，在这儿说了‘好’是不能退货的。”她把手伸过来，“好。别迟到。”`,`Lucía looks at the ring a long time — that same pricing look. "City boy, out here a yes doesn't come with a return policy." She holds out her hand. "Yes. Don't be late."`,`A Lucía olha muito tempo para o anel — o mesmo olhar de quem avalia. «Menino da cidade, aqui um sim não tem devolução.» Estende a mão. «Sim. Não te atrases.»`),
 vow:t(`露西娅没拿稿子：“我不会说漂亮话。你迟到我就骂你，你病了我就守着你，南井的水我每年替你验一次。一辈子。”`,`Lucía has no notes. "I don't do pretty words. You're late, I'll yell. You're sick, I'll sit up with you. I'll test the south well for you every year. For life."`,`A Lucía não traz papel. «Não sei dizer coisas bonitas. Se te atrasares, ralho contigo. Se adoeceres, fico acordada contigo. A água do poço sul, testo-a por ti todos os anos. A vida inteira.»`),
 baby:t(`露西娅接过孩子，熟练得像接一头小牛，然后手突然抖了：“我接过两百头牛犊。这个不一样。这个是我们的。”`,`Lucía takes the child as easily as she'd take a calf — then her hands start to shake. "I've caught two hundred calves. This is different. This one's ours."`,`A Lucía pega na criança com a mesma facilidade com que pega num vitelo — e depois as mãos começam a tremer. «Já ajudei a nascer duzentos vitelos. Isto é diferente. Isto é nosso.»`),
 moment:()=>({title:t('凌晨两点的牛棚','The barn at 2 a.m.','O estábulo às duas da manhã'),meta:f2_M('lucia'),
  text:[t(`产犊季。凌晨两点，露西娅的电话响了：北边一头头胎母牛卡住了，贝托的腰又犯了。她已经三天没睡整觉，一边套靴子一边骂。`,`Calving season. At 2 a.m. Lucía's phone goes: a first-time heifer stuck up on the north pasture, and Beto's back is out again. She hasn't slept a full night in three days. She swears while she pulls her boots on.`,`Época de partos. Às duas da manhã toca o telemóvel da Lucía: uma novilha de primeira cria encravada no pasto norte, e o Beto com as costas outra vez em baixo. Ela não dorme uma noite inteira há três dias. Pragueja enquanto calça as botas.`),
   t(`她在门口回头看你——不是在估价，是在问。`,`At the door she looks back at you. Not pricing you this time. Asking.`,`À porta, olha para trás. Desta vez não te está a avaliar. Está a perguntar.`)],
  choices:[
   {t:t('穿上衣服跟她去，按住牛头 · 信任 +1 · 德州味 +2','Get dressed and go hold the cow\'s head · Trust +1 · Texanness +2','Vestir-te e ir segurar a cabeça da vaca · Confiança +1 · Texanidade +2'),fx:()=>{addTrust('lucia',1);stat('tex',2)}},
   {t:t('留下来，天亮前把早饭和咖啡送到牛棚 · 信任 +1 · 手艺 +1','Stay, and have breakfast and coffee at the barn by dawn · Trust +1 · Craft +1','Ficar e levar o pequeno-almoço e o café ao estábulo antes de amanhecer · Confiança +1 · Ofício +1'),fx:()=>{addTrust('lucia',1);stat('oficio',1);S.cash-=15}},
   {t:t('“明天店里还要开门。”翻身接着睡','"The shop opens tomorrow." Roll over and go back to sleep','«A loja abre amanhã.» Virar-te e voltar a dormir'),fx:()=>{addTrust('lucia',-1)}}]})
});
f2_home('lucia',k=>t(`多年以后，南井边那张双人长凳坐不下了。${k}管你叫“城里人”，是跟妈妈学的；露西娅每年春天照样验一次井水，验完在本子上写：干净。`,`Years later, the two-seat bench by the south well is too small. ${k} calls you "city boy" — learned it from Lucía. Every spring she still tests the well, and writes in her notebook: clean.`,`Anos depois, o banco de dois lugares junto ao poço sul já não chega. ${k} chama-te «menino da cidade» — aprendeu com a mãe. Todas as primaveras a Lucía ainda testa a água e escreve no caderno: limpa.`),
 t(`多年以后，南井边的长凳被坐得发亮。露西娅还叫你“城里人”，只是现在那三个字的意思是“我的”。`,`Years later, the bench by the south well is worn smooth. Lucía still calls you "city boy." These days it just means "mine."`,`Anos depois, o banco junto ao poço sul está gasto e liso. A Lucía ainda te chama «menino da cidade». Agora quer só dizer «meu».`));

/* ---------- JOLENE ---------- */
Object.assign(PARTNER.jolene,{
 yes:t(`乔琳把戒指先套在小指上，又换到无名指：“咱们的规矩是谁也不劝谁留。可你没劝——你是问。”她咧嘴一笑，“那我答：好。”`,`Jolene tries the ring on her pinky first, then moves it over. "Our rule is nobody talks anybody into staying. But you didn't talk. You asked." She grins. "So here's my answer: yes."`,`A Jolene experimenta o anel no mindinho primeiro, depois muda-o de dedo. «A nossa regra é ninguém convencer ninguém a ficar. Mas tu não convenceste. Perguntaste.» Sorri. «Então a resposta é: sim.»`),
 vow:t(`乔琳的誓词是唱出来的：“我写过一百首关于离开的歌。从今天起，我写回来的歌——每一次，都回到你这儿。”`,`Jolene sings her vow. "I've written a hundred songs about leaving. From today I write the coming-back kind — and every time, I come back to you."`,`A Jolene canta os votos. «Escrevi cem canções sobre partir. A partir de hoje escrevo das de voltar — e volto sempre para ti.»`),
 baby:t(`乔琳抱着孩子，轻轻哼起《圣鲁伊斯的退潮》，哼到一半笑了：“得改词了。这首歌现在是三个人的。”`,`Jolene holds the child and hums "Low Tide in San Luís," then laughs halfway through. "Gotta rewrite it. This song's got three people in it now."`,`A Jolene pega na criança e trauteia «Maré Baixa em San Luís», e a meio ri-se. «Tenho de mudar a letra. Agora esta canção é de três.»`),
 moment:()=>({title:t('暖场三周','Three weeks of opening slots','Três semanas de primeiras partes'),meta:f2_M('jolene'),
  text:[t(`纳什维尔一个歌手请乔琳巡演暖场，三周，十一个城市。她把邮件给你看，手指压着“接受”按钮，没按下去。`,`A Nashville act wants Jolene to open for them: three weeks, eleven cities. She shows you the email with her thumb over "accept," not pressing it.`,`Um artista de Nashville quer a Jolene na primeira parte da digressão: três semanas, onze cidades. Mostra-te o e-mail com o polegar em cima de «aceitar», sem carregar.`),
   t(`厄尔在吧台后面擦杯子，装作没听见，擦的是同一个杯子。`,`Behind the bar Earl polishes a glass and pretends not to hear. It's the same glass he's been polishing all along.`,`Atrás do balcão, o Earl limpa um copo e finge não ouvir. É o mesmo copo há dez minutos.`)],
  choices:[
   {t:t('替她按下“接受”：“吧台我替你看。” · 信任 +1 · 口碑 +1','Press "accept" for her: "I\'ll mind the bar." · Trust +1 · Reputation +1','Carregar em «aceitar» por ela: «Eu tomo conta do balcão.» · Confiança +1 · Reputação +1'),fx:()=>{addTrust('jolene',1);S.rep+=1}},
   {t:t('[$150] 关店两天，开车去看她最后一场 · 信任 +2','[$150] Close for two days and drive up for her last show · Trust +2','[$150] Fechar dois dias e ir ver o último concerto dela · Confiança +2'),req:()=>S.cash>=150||NEED('$150'),fx:()=>{addTrust('jolene',2);S.cash-=150}},
   {t:t('问她：“店里周末怎么办？”','Ask her: "What about weekends at the shop?"','Perguntar-lhe: «E os fins de semana na loja?»'),fx:()=>{addTrust('jolene',-1);S.cash+=60}}]})
});
f2_home('jolene',k=>t(`多年以后，孤星酒吧的点唱机里有乔琳的四张唱片。厄尔的老位置上坐着${k}，脚还够不着地，跟着拍子晃。`,`Years later, the Lone Star jukebox carries four of Jolene's records. ${k} sits on Earl's old stool, feet nowhere near the floor, swinging in time.`,`Anos depois, a jukebox do Lone Star tem quatro discos da Jolene. ${k} senta-se no banco antigo do Earl, os pés longe do chão, a balançar ao ritmo.`),
 t(`多年以后，乔琳每次巡演回来，第一件事都是推开店门喊一声“我回来了”。她写回来的歌，已经写了一整张唱片。`,`Years later, every time Jolene gets back off the road, the first thing she does is push open the shop door and holler "I'm home." Her coming-back songs fill a whole record now.`,`Anos depois, sempre que a Jolene volta da estrada, a primeira coisa que faz é abrir a porta da loja e gritar «Cheguei». As canções de voltar já enchem um disco inteiro.`));

/* ---------- SAVANNAH ---------- */
Object.assign(PARTNER.savannah,{
 yes:t(`萨凡纳没看戒指，先看你：“我嫁过一次。上一次没人问我想不想。”她停了停，“这一次我想。好。”`,`Savannah doesn't look at the ring. She looks at you. "I've been married once. Last time nobody asked if I wanted to." A pause. "This time I do. Yes."`,`A Savannah não olha para o anel. Olha para ti. «Já fui casada uma vez. Dessa vez ninguém me perguntou se eu queria.» Uma pausa. «Desta vez quero. Sim.»`),
 vow:t(`萨凡纳说：“我不要你保证永远。我只要你每年问我一次，我喜欢什么花。我也每年问你一次。”`,`Savannah says, "I don't need you to promise forever. Just ask me once a year what flowers I like. And I'll ask you."`,`A Savannah diz: «Não precisas de me prometer para sempre. Pergunta-me uma vez por ano de que flores gosto. E eu pergunto-te a ti.»`),
 baby:t(`萨凡纳把孩子贴在胸口，闻了闻头顶：“比牡丹还香。你看，德州到底还是让我种活了一样想要的东西。”`,`Savannah holds the child against her chest and breathes in. "Sweeter than peonies. See? Texas finally let me grow something I wanted."`,`A Savannah encosta a criança ao peito e cheira-lhe a cabeça. «Cheira melhor do que peónias. Vês? O Texas lá me deixou fazer crescer uma coisa que eu queria.»`),
 moment:()=>({title:t('情人节的订单','The Valentine\'s order','A encomenda do Dia dos Namorados'),meta:f2_M('savannah'),
  text:[t(`情人节早上，花店门口排起了队。轮到第七个，是普鲁伊特警长。他要一打红玫瑰，送给他的新女朋友。`,`Valentine's morning, there's a line out the flower shop door. Seventh in line is Sheriff Pruitt. A dozen red roses, for his new girlfriend.`,`Manhã do Dia dos Namorados, há fila à porta da florista. O sétimo é o xerife Pruitt. Uma dúzia de rosas vermelhas, para a namorada nova.`),
   t(`萨凡纳给玫瑰去刺，刀往外推。你站在柜台后面，系着她的围裙。`,`Savannah strips the thorns, blade pushed outward. You're behind the counter in her apron.`,`A Savannah tira os espinhos com a faca virada para fora. Tu estás atrás do balcão, com o avental dela.`)],
  choices:[
   {t:t('照常收钱，祝他节日快乐 · 信任 +1 · 口碑 +1','Ring him up and wish him a happy Valentine\'s · Trust +1 · Reputation +1','Cobrar como a qualquer outro e desejar-lhe bom dia · Confiança +1 · Reputação +1'),fx:()=>{addTrust('savannah',1);S.rep+=1;S.cash+=40}},
   {t:t('退到后屋，让她自己处理 · 信任 +2','Step into the back room and let her handle it · Trust +2','Ir para as traseiras e deixá-la tratar disso · Confiança +2'),fx:()=>{addTrust('savannah',2)}},
   {t:t('当着他的面亲她一下 · 魅力 +2','Kiss her, right in front of him · Charm +2','Dar-lhe um beijo, mesmo à frente dele · Charme +2'),fx:()=>{stat('charme',2);addTrust('savannah',-1)}}]})
});
f2_home('savannah',k=>t(`多年以后，花店后院有一小片牡丹，是你们试了六年才种活的。每个星期五，${k}负责把猪排包送到店里，再把剩下的花抱回家。`,`Years later, there's a small bed of peonies behind the flower shop — six years of trying before they took. Every Friday ${k} carries the pork sandwiches over, and carries the leftover flowers home.`,`Anos depois, há um pequeno canteiro de peónias atrás da florista — seis anos de tentativas até pegarem. Todas as sextas, ${k} leva as sandes de porco à loja e traz as flores que sobram para casa.`),
 t(`多年以后，花店后院有一小片牡丹，是你们试了六年才种活的。萨凡纳每年还是问你喜欢什么花，你每年答的都一样。`,`Years later, there's a small bed of peonies behind the flower shop — six years of trying before they took. Savannah still asks every year what flowers you like. Your answer never changes.`,`Anos depois, há um pequeno canteiro de peónias atrás da florista — seis anos de tentativas até pegarem. A Savannah ainda te pergunta todos os anos de que flores gostas. A resposta é sempre a mesma.`));

/* ---------- CLARA ---------- */
Object.assign(PARTNER.clara,{
 yes:t(`克拉拉推过来一张借书卡，背面用葡语写着“是”。“我练了一个星期，”她说，“怕说出口的时候发音不对。”`,`Clara slides a library card across. On the back, in Portuguese, it says "yes." "I practised for a week," she says. "I was afraid I'd say it wrong out loud."`,`A Clara empurra um cartão de leitor. No verso, em português, está escrito «sim». «Treinei uma semana», diz. «Tinha medo de o dizer mal em voz alta.»`),
 vow:t(`克拉拉念她的誓词：“佩索阿说他什么也不是。我不同意。你是我读过最好的一本书，我不打算还了。”`,`Clara reads her vow. "Pessoa said he was nothing. I disagree. You're the best book I've ever read, and I'm not returning you."`,`A Clara lê os votos. «O Pessoa dizia que não era nada. Discordo. És o melhor livro que já li, e não te vou devolver.»`),
 baby:t(`克拉拉抱着孩子，小声念了一句葡语，又念了一遍英语：“两种都给你。这样你以后就不用翻译了。”`,`Clara holds the child and whispers a line in Portuguese, then again in English. "You get both. That way you'll never need a translation."`,`A Clara pega na criança e sussurra uma frase em português, e depois outra vez em inglês. «Ficas com as duas. Assim nunca vais precisar de tradução.»`),
 moment:()=>({title:t('双语故事会','Bilingual story hour','Hora do conto bilingue'),meta:f2_M('clara'),
  text:[t(`克拉拉在图书馆办了每周六的“葡英双语故事会”。第一周来了九个孩子，一半是亚速尔老移民的曾孙。`,`Clara starts a Saturday Portuguese–English story hour at the library. Nine kids come the first week, half of them great-grandchildren of the old Azorean families.`,`A Clara começa uma hora do conto bilingue aos sábados na biblioteca. Na primeira semana aparecem nove crianças, metade bisnetos das velhas famílias açorianas.`),
   t(`第二周，一位镇议员写信给馆长：“这是美国的图书馆。”克拉拉把信夹进了佩索阿那本书里。`,`The second week a council member writes to the head librarian: "This is an American library." Clara files the letter inside her copy of Pessoa.`,`Na segunda semana, um vereador escreve à diretora: «Esta é uma biblioteca americana.» A Clara guarda a carta dentro do livro do Pessoa.`)],
  choices:[
   {t:t('周六去念葡语那一半 · 信任 +1 · 乡愁 +2','Go on Saturday and read the Portuguese half · Trust +1 · Homesickness +2','Ir no sábado ler a metade portuguesa · Confiança +1 · Saudade +2'),fx:()=>{addTrust('clara',1);stat('saud',2)}},
   {t:t('[$40] 每周带一盘蛋挞，请议员的孙子也来 · 口碑 +2','[$40] Bring custard tarts every week and invite the councilman\'s grandson · Reputation +2','[$40] Levar pastéis de nata todas as semanas e convidar o neto do vereador · Reputação +2'),req:()=>S.cash>=40||NEED('$40'),fx:()=>{S.cash-=40;S.rep+=2;addTrust('clara',1)}},
   {t:t('劝她别惹麻烦 · 信任 −1','Tell her not to stir up trouble · Trust −1','Dizer-lhe para não arranjar problemas · Confiança −1'),fx:()=>{addTrust('clara',-1)}}]})
});
f2_home('clara',k=>t(`多年以后，社区大学图书馆多了一排书架，标签是“若泽烧烤店捐赠”，全是葡语书。借阅卡上最常出现的名字是${k}。`,`Years later, the college library has a new row of shelves labelled "Donated by Zé's Churrasco," all Portuguese books. The name that shows up most on the checkout cards is ${k}.`,`Anos depois, a biblioteca da faculdade tem uma estante nova com a etiqueta «Oferta do Zé's Churrasco», toda de livros em português. O nome que mais aparece nos cartões de requisição é ${k}.`),
 t(`多年以后，克拉拉的护照盖满了章，其中一半是里斯本。可她每次回来，都说圣鲁伊斯的楼梯最好爬——因为只有一级，就是店门口那一级。`,`Years later, Clara's passport is full of stamps, half of them Lisbon. But every time she comes back she says San Luís has the best stairs — there's only one, the step at the shop door.`,`Anos depois, o passaporte da Clara está cheio de carimbos, metade de Lisboa. Mas sempre que volta diz que San Luís tem as melhores escadas — só há um degrau, o da porta da loja.`));

/* ---------- HANNAH ---------- */
Object.assign(PARTNER.hannah,{
 yes:t(`汉娜按住你的手腕数脉：“一百二。你是认真的。”她自己把戒指戴上，“诊断：我也是。”`,`Hannah takes your pulse at the wrist. "A hundred and twenty. You mean it." She puts the ring on herself. "Diagnosis: so do I."`,`A Hannah toma-te o pulso. «Cento e vinte. Estás a falar a sério.» Põe ela própria o anel. «Diagnóstico: eu também.»`),
 vow:t(`汉娜说：“先说最坏的：我会值夜班，会累，会忘记吃饭。再说最可能的：我每天都会回家。”`,`Hannah says, "Worst case first: I'll work nights, I'll be tired, I'll forget to eat. Now the most likely: I'll come home to you every day."`,`A Hannah diz: «Primeiro o pior: vou fazer noites, vou andar cansada, vou esquecer-me de comer. Agora o mais provável: volto para ti todos os dias.»`),
 baby:t(`汉娜抱过一百多个新生儿，抱起这一个时却忘了所有步骤：“我得重新学。这一个，我不是医生。”`,`Hannah has held more than a hundred newborns, and with this one she forgets every step. "I'll have to learn it over. With this one, I'm not the doctor."`,`A Hannah já pegou em mais de cem recém-nascidos, e com este esquece-se de tudo. «Vou ter de aprender outra vez. Com esta criança, não sou médica.»`),
 moment:()=>({title:t('明尼苏达的电话','A call from Minnesota','Uma chamada do Minnesota'),meta:f2_M('hannah'),
  text:[t(`养老院打来电话。汉娜的父亲今天早上叫了她的名字——三年来第一次。护士说，这样的清醒不会长。`,`The nursing home calls. This morning Hannah's father said her name — the first time in three years. The nurse says a clear spell like this won't last.`,`Telefonam do lar. Esta manhã o pai da Hannah disse o nome dela — a primeira vez em três anos. A enfermeira diz que um momento de lucidez assim não dura.`),
   t(`汉娜站在诊所门口，没点烟，只是把烟盒捏扁了。`,`Hannah stands outside the clinic. She doesn't light a cigarette. She just crushes the pack.`,`A Hannah está à porta da clínica. Não acende o cigarro. Só esmaga o maço.`)],
  choices:[
   {t:t('[$250] 订两张今晚去明尼苏达的机票 · 信任 +2','[$250] Book two seats to Minnesota tonight · Trust +2','[$250] Reservar dois lugares para o Minnesota esta noite · Confiança +2'),req:()=>S.cash>=250||NEED('$250'),fx:()=>{S.cash-=250;addTrust('hannah',2)}},
   {t:t('马上打视频过去，你在旁边煮一锅羽衣甘蓝汤给他看 · 信任 +1 · 手艺 +1','Video-call him now while you cook kale soup in the background · Trust +1 · Craft +1','Fazer já uma videochamada enquanto cozinhas caldo verde ao fundo · Confiança +1 · Ofício +1'),fx:()=>{addTrust('hannah',1);stat('oficio',1)}},
   {t:t('先替她把下午的病人排开 · 口碑 +1','Clear her afternoon patients first · Reputation +1','Desmarcar primeiro os doentes da tarde · Reputação +1'),fx:()=>{S.rep+=1}}]})
});
f2_home('hannah',k=>t(`多年以后，诊所墙上挂着一张蜡笔画：一个穿白大褂的人，和一锅很大的汤。镇上的病人叫她汉娜医生，${k}叫她妈妈。`,`Years later, there's a crayon drawing on the clinic wall: a person in a white coat beside a very large pot of soup. The town calls her Dr. Hannah. ${k} calls her Mom.`,`Anos depois, há um desenho a lápis de cera na parede da clínica: uma pessoa de bata branca ao lado de uma panela de sopa enorme. A vila chama-lhe doutora Hannah. ${k} chama-lhe mãe.`),
 t(`多年以后，诊所门口那个“不算数”的烟灰缸种上了迷迭香。汉娜每晚下班都回家，最坏的情况一次也没发生。`,`Years later, the "doesn't count" ashtray by the clinic door has rosemary growing in it. Hannah comes home every night. The worst case never happened once.`,`Anos depois, o cinzeiro «que não conta» à porta da clínica tem alecrim plantado. A Hannah volta para casa todas as noites. O pior nunca aconteceu.`));

/* ---------- BROOKE ---------- */
Object.assign(PARTNER.brooke,{
 yes:t(`布鲁克把地图摊在引擎盖上，在圣鲁伊斯那个圈外面又画了一圈。“两个圈的意思是：好。我停在这儿——不是停下来。”`,`Brooke spreads the map on the hood and draws a second circle around San Luís. "Two circles means yes. I'm stopping here. That's not the same as stopping."`,`A Brooke abre o mapa em cima do capô e desenha um segundo círculo à volta de San Luís. «Dois círculos quer dizer sim. Fico aqui. Não é o mesmo que parar.»`),
 vow:t(`布鲁克说：“我不保证不走。我保证每一条路的尽头都是你。葡萄干作证。”葡萄干打了个响鼻。`,`Brooke says, "I won't promise not to leave. I promise every road ends at you. Raisin's my witness." Raisin snorts.`,`A Brooke diz: «Não prometo não partir. Prometo que todas as estradas acabam em ti. O Passa é testemunha.» O Passa bufa.`),
 baby:t(`布鲁克抱孩子的样子，像第一次骑一匹没驯过的马，胳膊僵直：“别笑。这比绕桶难多了。”孩子抓住她的辫子，她就不怕了。`,`Brooke holds the child like she's on an unbroken horse for the first time, arms stiff. "Don't laugh. This is way harder than barrels." The child grabs her braid, and she stops being scared.`,`A Brooke pega na criança como quem monta um cavalo por domar pela primeira vez, braços tesos. «Não te rias. Isto é muito mais difícil do que os barris.» A criança agarra-lhe a trança, e o medo passa.`),
 moment:()=>({title:t('葡萄干老了','Raisin is getting old','O Passa está a ficar velho'),meta:f2_M('brooke'),
  text:[t(`兽医说葡萄干的前腿撑不过下一个赛季了。布鲁克听完，什么也没说，把马拖车擦了一整个下午。`,`The vet says Raisin's front legs won't last another season. Brooke says nothing. She spends the whole afternoon washing the trailer.`,`O veterinário diz que as patas da frente do Passa não aguentam outra época. A Brooke não diz nada. Passa a tarde inteira a lavar o atrelado.`),
   t(`傍晚她问你：“马退休了，骑手怎么办？”`,`At dusk she asks you: "When the horse retires, what's the rider supposed to do?"`,`Ao fim da tarde pergunta-te: «Quando o cavalo se reforma, o que é que a cavaleira faz?»`)],
  choices:[
   {t:t('[$200] 在雷耶斯牧场租一块草场给葡萄干养老 · 信任 +2','[$200] Rent a pasture at the Reyes Ranch for Raisin\'s retirement · Trust +2','[$200] Alugar um pasto no rancho dos Reyes para a reforma do Passa · Confiança +2'),req:()=>S.cash>=200||NEED('$200'),fx:()=>{S.cash-=200;addTrust('brooke',2)}},
   {t:t('“教镇上的孩子绕桶。路换个方向跑。” · 信任 +1 · 口碑 +2','"Teach the town kids barrels. Run the road the other way." · Trust +1 · Reputation +2','«Ensina os miúdos da vila a correr barris. Faz a estrada ao contrário.» · Confiança +1 · Reputação +2'),fx:()=>{addTrust('brooke',1);S.rep+=2}},
   {t:t('[骑马 2] 陪葡萄干跑最后一圈慢的 · 德州味 +2','[Riding 2] Take Raisin round for one last slow lap · Texanness +2','[Equitação 2] Dar com o Passa uma última volta devagar · Texanidade +2'),req:()=>S.course.ride>=2||NEED(t('骑马 2','Riding 2','Equitação 2')),fx:()=>{stat('tex',2);addTrust('brooke',1)}}]})
});
f2_home('brooke',k=>t(`多年以后，马拖车里多了一副小号马鞍。布鲁克的地图上，圣鲁伊斯那一点被描成了一个黑洞，${k}说那是“家的引力”。`,`Years later, there's a child-size saddle in the trailer. On Brooke's map, San Luís has been circled so many times it's a black hole. ${k} calls it "home gravity."`,`Anos depois, há uma sela pequenina no atrelado. No mapa da Brooke, San Luís foi rodeada tantas vezes que é um buraco negro. ${k} chama-lhe «a gravidade de casa».`),
 t(`多年以后，布鲁克的地图上，圣鲁伊斯那一点被描成了一个黑洞。她每次出发前都要摸一下，像摸葡萄干的鼻子。`,`Years later, on Brooke's map, San Luís has been circled so many times it's a black hole. She touches it before every trip, like she used to touch Raisin's nose.`,`Anos depois, no mapa da Brooke, San Luís foi rodeada tantas vezes que é um buraco negro. Ela toca-lhe antes de cada viagem, como tocava no focinho do Passa.`));

/* ---------- MEGAN ---------- */
Object.assign(PARTNER.megan,{
 yes:t(`梅根看了看四周——你特意选在主街谁都看得见的地方。她笑了，眼泪先出来：“你站过来了。好。当着所有人，好。”`,`Megan looks around — you chose the spot on Main Street where everybody can see. She laughs, and the tears come first. "You stood up with me. Yes. In front of everyone, yes."`,`A Megan olha à volta — escolheste o sítio da rua principal onde toda a gente vê. Ri-se, e as lágrimas chegam primeiro. «Vieste para o meu lado. Sim. À frente de todos, sim.»`),
 vow:t(`梅根说：“我这辈子都站在别人看得见的地方。从今天起，我站在你旁边，让他们看个够。”`,`Megan says, "My whole life I've stood where people could see me. From today I'll stand beside you, and they can look all they like."`,`A Megan diz: «A vida inteira estive onde toda a gente me via. A partir de hoje fico ao teu lado, e eles que olhem à vontade.»`),
 baby:t(`梅根抱着孩子，唱的不是赞美诗，是她在乐谱边上偷偷改的和声：“这一段谁也没听过。第一个听的是你。”`,`Megan holds the child and sings — not a hymn, but the harmony she pencilled in the margins. "Nobody's ever heard this part. You're the first."`,`A Megan pega na criança e canta — não um hino, mas a harmonia que escreveu às escondidas na margem da partitura. «Ninguém ouviu esta parte. Ouves tu primeiro.»`),
 moment:()=>({title:t('牧师来吃饭','The pastor comes to dinner','O pastor vem jantar'),meta:f2_M('megan'),
  text:[t(`戴尔牧师第一次来家里吃星期天晚饭。他坐得笔直，盯着桌上那瓶葡萄酒，像盯着讲台下的一个罪人。`,`Pastor Dale comes to Sunday dinner at your place for the first time. He sits bolt upright and stares at the bottle of wine on the table like it's a sinner in the front pew.`,`O pastor Dale vem jantar a vossa casa a um domingo pela primeira vez. Senta-se muito direito e olha para a garrafa de vinho como se fosse um pecador na primeira fila.`),
   t(`梅根在桌下捏了一下你的手。`,`Under the table, Megan squeezes your hand.`,`Debaixo da mesa, a Megan aperta-te a mão.`)],
  choices:[
   {t:t('把酒收起来，换上冰柠檬水 · 戴尔信任 +2','Put the wine away and bring iced lemonade · Dale trust +2','Guardar o vinho e trazer limonada fresca · Confiança do Dale +2'),fx:()=>{addTrust('dale',2)}},
   {t:t('请梅根来做饭前祷告 · 信任 +2','Ask Megan to say grace · Trust +2','Pedir à Megan para dar graças · Confiança +2'),fx:()=>{addTrust('megan',2);addTrust('dale',1)}},
   {t:t('照常给自己倒一杯 · 德州味 +1','Pour yourself a glass as usual · Texanness +1','Servir-te um copo como sempre · Texanidade +1'),fx:()=>{stat('tex',1);addTrust('dale',-1)}}]})
});
f2_home('megan',k=>t(`多年以后，梅根在休斯敦和圣鲁伊斯之间教声乐。星期天下午，她和${k}总坐在店里主街窗边那张桌子，谁都看得见。`,`Years later, Megan teaches voice between Houston and San Luís. On Sunday afternoons she and ${k} sit at the window table on Main Street, where anyone can see.`,`Anos depois, a Megan dá aulas de canto entre Houston e San Luís. Aos domingos à tarde, ela e ${k} sentam-se na mesa da janela que dá para a rua principal, onde toda a gente vê.`),
 t(`多年以后，梅根在休斯敦和圣鲁伊斯之间教声乐。星期天的唱诗班里，那段偷改的和声终于印进了乐谱。戴尔牧师说，是他让加的。`,`Years later, Megan teaches voice between Houston and San Luís. Her secret harmony is printed in the Sunday choir book now. Pastor Dale says it was his idea.`,`Anos depois, a Megan dá aulas de canto entre Houston e San Luís. A harmonia secreta dela já está impressa no livro do coro. O pastor Dale diz que a ideia foi dele.`));

/* ---------- COLLEEN ---------- */
Object.assign(PARTNER.colleen,{
 yes:t(`科琳掏出笔记本：“等一下，我要记准确。”她写下日期、时间、地点，然后写：“回答：是。消息来源：本人。”`,`Colleen pulls out her notebook. "Hold on, I want this accurate." She writes the date, the time, the place. Then: "Answer: yes. Source: me."`,`A Colleen tira o caderno. «Espera, quero isto exato.» Escreve a data, a hora, o local. Depois: «Resposta: sim. Fonte: a própria.»`),
 vow:t(`科琳说：“我只写核实过的事。我核实了一整年，来源交叉比对过三遍。结论是你。”`,`Colleen says, "I only print what I've verified. I spent a year on this, cross-checked three times. The finding is you."`,`A Colleen diz: «Só publico o que confirmei. Levei um ano nisto, confirmei com três fontes. A conclusão és tu.»`),
 baby:t(`科琳抱着孩子，第一次忘了掏笔记本：“我不记了。这一刻，我想自己记住。”`,`Colleen holds the child and, for once, forgets her notebook. "I'm not writing this down. This one I want to remember myself."`,`A Colleen pega na criança e, pela primeira vez, esquece-se do caderno. «Não vou apontar. Isto quero lembrar-me eu.»`),
 moment:()=>({title:t('《号角报》要卖了','The Clarion is for sale','O Clarion está à venda'),meta:f2_M('colleen'),
  text:[t(`《号角报》的老板要退休，报纸挂牌出售。唯一的买家是一家连锁媒体，他们只想要订户名单。`,`The Clarion's owner is retiring, and the paper is up for sale. The only buyer is a media chain that just wants the subscriber list.`,`O dono do Clarion vai reformar-se e o jornal está à venda. O único comprador é uma cadeia de media que só quer a lista de assinantes.`),
   t(`科琳在餐桌上摊开账本，写下第一行：“不要相信任何人——”然后停住了，看着你。`,`Colleen spreads the books on the kitchen table and writes the first line: "Trust nobody —" Then she stops, and looks at you.`,`A Colleen abre as contas na mesa da cozinha e escreve a primeira linha: «Não confies em ninguém —» Depois para, e olha para ti.`)],
  choices:[
   {t:t('[$300] 拿店里的积蓄跟她一起买下报社 · 信任 +2 · 口碑 +2','[$300] Put the shop\'s savings in and buy the paper with her · Trust +2 · Reputation +2','[$300] Pôr as poupanças da loja e comprar o jornal com ela · Confiança +2 · Reputação +2'),req:()=>S.cash>=300||NEED('$300'),fx:()=>{S.cash-=300;addTrust('colleen',2);S.rep+=2}},
   {t:t('在每一期都登一整版若泽烧烤店广告 · 口碑 +1','Take out a full-page ad for Zé\'s in every issue · Reputation +1','Pôr um anúncio de página inteira do Zé\'s em cada número · Reputação +1'),fx:()=>{S.cash-=60;S.rep+=1;addTrust('colleen',1)}},
   {t:t('请老菲茨杰拉德出个主意 · 信任 +1','Ask old Fitzgerald what he\'d do · Trust +1','Perguntar ao velho Fitzgerald o que faria · Confiança +1'),fx:()=>{addTrust('colleen',1)}}]})
});
f2_home('colleen',k=>t(`多年以后，《号角报》还在每周四出版。头版底下有个小专栏，写一家葡萄牙烧烤店的日常；挨家挨户送报的，是${k}。`,`Years later, the Clarion still comes out every Thursday. Below the fold there's a little column about the daily life of a Portuguese grill — and the kid throwing papers on every porch is ${k}.`,`Anos depois, o Clarion ainda sai todas as quintas. Na primeira página há uma coluna pequena sobre o dia a dia de uma churrasqueira portuguesa — e quem distribui o jornal porta a porta é ${k}.`),
 t(`多年以后，《号角报》还在每周四出版。头版底下有个小专栏，写一家葡萄牙烧烤店的日常，署名是两个人。`,`Years later, the Clarion still comes out every Thursday. Below the fold there's a little column about the daily life of a Portuguese grill. It has two bylines.`,`Anos depois, o Clarion ainda sai todas as quintas. Na primeira página há uma coluna pequena sobre o dia a dia de uma churrasqueira portuguesa. É assinada por dois.`));

/* ---------- WADE ---------- */
Object.assign(PARTNER.wade,{
 yes:t(`韦德听完，把帽子摘下来，在手里转了一圈，又戴回去。“好。”过了很久，他又加了一个字：“嗯。”这是他说过最长的情话。`,`Wade hears you out, takes off his hat, turns it once in his hands and puts it back on. "Yes." A long while later he adds one more word: "Yep." It's the longest love speech he's ever made.`,`O Wade ouve-te até ao fim, tira o chapéu, roda-o uma vez nas mãos e volta a pô-lo. «Sim.» Muito depois acrescenta mais uma palavra: «Pois.» É a declaração de amor mais longa que alguma vez fez.`),
 vow:t(`韦德的誓词只有三句，他练了一个月：“我话少。我说要修的，都会修。我说要来的，每天傍晚都来。”`,`Wade's vow is three sentences. He practised for a month. "I don't talk much. What I say I'll fix, I fix. What I say I'll come for, I come for — every evening."`,`Os votos do Wade são três frases. Treinou um mês. «Falo pouco. O que digo que arranjo, arranjo. Onde digo que venho, venho — todas as tardes.»`),
 baby:t(`韦德一只手就托住了孩子，像托一顶帽子。他看了很久，只说：“戴好帽子。太阳会把你脑子晒坏。”`,`Wade holds the child in one hand, the way he'd hold a hat. He looks a long time, and all he says is: "Keep your hat on. Sun'll cook your brains."`,`O Wade segura a criança numa só mão, como seguraria um chapéu. Olha muito tempo, e só diz: «Põe o chapéu. O sol dá-te cabo da cabeça.»`),
 moment:()=>({title:t('饲料店','The feed store','A loja de rações'),meta:f2_M('wade'),
  text:[t(`周六早上，饲料店。收银的老头看了看你，又看了看韦德：“你那位室友？”`,`Saturday morning at the feed store. The old man at the register looks at you, then at Wade. "Your roommate?"`,`Sábado de manhã, na loja de rações. O velho da caixa olha para ti, depois para o Wade. «O teu colega de casa?»`),
   t(`韦德把一袋饲料扛上肩，停了两秒。“丈夫。”他说完，把钱放在柜台上。`,`Wade swings a sack of feed onto his shoulder and stops for two seconds. "Husband," he says, and puts the money on the counter.`,`O Wade põe um saco de ração ao ombro e para dois segundos. «Marido», diz, e põe o dinheiro no balcão.`)],
  choices:[
   {t:t('什么也不说，帮他把剩下的袋子扛上车 · 信任 +2','Say nothing; help him load the rest onto the truck · Trust +2','Não dizer nada; ajudá-lo a carregar o resto para a carrinha · Confiança +2'),fx:()=>{addTrust('wade',2);stat('tex',1)}},
   {t:t('跟老头握手，请他周五来店里吃肋排 · 口碑 +2','Shake the old man\'s hand and invite him for ribs on Friday · Reputation +2','Apertar a mão ao velho e convidá-lo para costelas na sexta · Reputação +2'),fx:()=>{S.rep+=2;addTrust('wade',1)}},
   {t:t('[魅力 50] 补一句：“他做饭比我还好。” · 魅力 +1','[Charm 50] Add: "He cooks better than me, too." · Charm +1','[Charme 50] Acrescentar: «E cozinha melhor do que eu.» · Charme +1'),req:()=>charm()>=50||NEED(t('魅力 50','Charm 50','Charme 50')),fx:()=>{stat('charme',1);addTrust('wade',1)}}]})
});
f2_home('wade',k=>t(`多年以后，北边那座谷仓门背后钉着四样东西：他母亲的照片、1987 年的奖带、你画的第一张图纸，和${k}的第一顶帽子。傍晚按喇叭的，现在是坐在副驾上的${k}。`,`Years later, four things are nailed inside the north barn door: his mother's photo, a 1987 rodeo ribbon, your first drawing, and ${k}'s first hat. These days it's ${k}, in the passenger seat, who honks the horn at dusk.`,`Anos depois, há quatro coisas pregadas por dentro da porta do celeiro norte: a fotografia da mãe dele, uma fita de rodeo de 1987, o teu primeiro desenho e o primeiro chapéu de ${k}. Agora é ${k}, no lugar do pendura, quem buzina ao fim da tarde.`),
 t(`多年以后，北边那座谷仓门背后钉着三样东西：他母亲的照片、1987 年的奖带、你画的第一张图纸。每天傍晚，喇叭还是只按一下。`,`Years later, three things are nailed inside the north barn door: his mother's photo, a 1987 rodeo ribbon, and your first drawing. Every evening the horn still honks just once.`,`Anos depois, há três coisas pregadas por dentro da porta do celeiro norte: a fotografia da mãe dele, uma fita de rodeo de 1987 e o teu primeiro desenho. Todas as tardes a buzina ainda toca só uma vez.`));

/* ---------- ASHLEY ---------- */
Object.assign(PARTNER.ashley,{
 yes:t(`阿什莉看了一眼秒表：“你单膝跪了四十秒了，膝盖别内扣。”然后她把秒表扔进草里：“好。我不计时了。”`,`Ashley glances at her stopwatch. "You've been on one knee forty seconds. Don't let it cave in." Then she tosses the stopwatch into the grass. "Yes. I'm done keeping time."`,`A Ashley olha para o cronómetro. «Estás de joelho há quarenta segundos. Não deixes o joelho fugir para dentro.» Depois atira o cronómetro para a relva. «Sim. Deixei de contar o tempo.»`),
 vow:t(`阿什莉说：“身体不会撒谎。我站在这儿，心跳一百四，你自己数。我愿意。”`,`Ashley says, "The body doesn't lie. I'm standing here at a hundred and forty beats a minute. Count it yourself. I do."`,`A Ashley diz: «O corpo não mente. Estou aqui com o coração a cento e quarenta. Conta tu. Aceito.»`),
 baby:t(`阿什莉抱着孩子，下意识检查了一遍姿势：头托好，腰别弯。然后她放弃了：“去他的姿势。”把脸贴了上去。`,`Ashley holds the child and runs her form check on instinct: head supported, back straight. Then she gives up. "Forget form." She presses her face close.`,`A Ashley pega na criança e verifica a postura por instinto: cabeça apoiada, costas direitas. Depois desiste. «Que se lixe a postura.» Encosta a cara.`),
 moment:()=>({title:t('膝盖','The knee','O joelho'),meta:f2_M('ashley'),
  text:[t(`那只旧膝盖终于要动手术了。医生说康复要四个月，每天早上练，练的时候会很难看。`,`The old knee finally needs surgery. The doctor says four months of rehab, every morning, and it won't be pretty.`,`O joelho antigo vai finalmente ser operado. O médico diz que são quatro meses de recuperação, todas as manhãs, e não vai ser bonito.`),
   t(`阿什莉把康复计划贴在冰箱上，在“为什么”那一栏空着。“我讨厌被人看见我站不稳。”`,`Ashley sticks the rehab plan on the fridge and leaves the "why" column blank. "I hate being seen when I can't stand straight."`,`A Ashley cola o plano de recuperação no frigorífico e deixa a coluna «porquê» em branco. «Detesto que me vejam sem conseguir estar de pé.»`)],
  choices:[
   {t:t('每天清晨五点陪她练，不看她，只数次数 · 信任 +2','Train beside her at 5 a.m. every day — don\'t watch, just count reps · Trust +2','Treinar ao lado dela às cinco da manhã — sem olhar, só a contar repetições · Confiança +2'),fx:()=>{addTrust('ashley',2);stat('tex',1)}},
   {t:t('在“为什么”那一栏替她写：周五晚上的比赛 · 信任 +1','Fill in the "why" for her: Friday night games · Trust +1','Escrever por ela na coluna «porquê»: os jogos de sexta à noite · Confiança +1'),fx:()=>{addTrust('ashley',1);S.rep+=1}},
   {t:t('请校队的孩子们轮流来家里陪她 · 口碑 +2','Get the team kids to take turns keeping her company · Reputation +2','Pedir aos miúdos da equipa que se revezem a fazer-lhe companhia · Reputação +2'),fx:()=>{S.rep+=2;addTrust('ashley',-0.5)}}]})
});
f2_home('ashley',k=>t(`多年以后，周五晚上，教练席正后方坐着两个人。${k}拿着秒表，替妈妈数暂停次数，数错了就被罚跑一圈。`,`Years later, on Friday nights, two people sit right behind the coaches' bench. ${k} holds the stopwatch and counts timeouts for Mom — get one wrong and it's a lap.`,`Anos depois, às sextas à noite, há duas pessoas sentadas logo atrás do banco dos treinadores. ${k} segura o cronómetro e conta os descontos de tempo pela mãe — quem se enganar dá uma volta à pista.`),
 t(`多年以后，阿什莉的膝盖又能跑了。周五晚上，她站在场边，你坐在教练席正后方，“为什么”那一栏写着同一个名字。`,`Years later, Ashley's knee runs again. On Friday nights she's on the sideline and you're right behind the bench, and the "why" column still has the same name in it.`,`Anos depois, o joelho da Ashley já corre outra vez. Às sextas à noite ela está na linha lateral e tu logo atrás do banco, e a coluna «porquê» ainda tem o mesmo nome.`));

/* ---------- INÊS ---------- */
Object.assign(PARTNER.ines,{
 yes:t(`伊内丝用里斯本的粗话骂了你一句——跟那次隔着安检玻璃一模一样。“我在机场外面站了两个小时，就等这一句。好。笨蛋，好。”`,`Inês swears at you in pure Lisbon — exactly like that time through the security glass. "I stood outside that airport two hours waiting for this. Yes. You idiot, yes."`,`A Inês diz-te um palavrão bem alfacinha — igualzinho ao daquela vez, do outro lado do vidro da segurança. «Estive duas horas à porta do aeroporto à espera disto. Sim. Seu parvo, sim.»`),
 vow:t(`伊内丝说：“我说过不会再站在安检外面等你。所以我不等了——这次我跟你走。走到哪儿，哪儿就是阿尔法马。”`,`Inês says, "I said I'd never stand outside security waiting for you again. So I'm done waiting. This time I go with you, and wherever we go is Alfama."`,`A Inês diz: «Disse que nunca mais ficava à porta da segurança à tua espera. Por isso já não espero. Desta vez vou contigo, e onde formos é Alfama.»`),
 baby:t(`伊内丝抱着孩子，第一句是葡语：“你外婆会疯掉的。”第二句还是葡语：“欢迎回家——两个家都算。”`,`Inês holds the child, and the first thing she says is in Portuguese: "Your grandmother is going to lose her mind." So is the second: "Welcome home — both of them count."`,`A Inês pega na criança e a primeira coisa que diz é: «A tua avó vai ficar maluca.» A segunda também: «Esta é a tua casa — e a outra também.»`),
 moment:()=>({title:t('签证续期','The visa renewal','A renovação do visto'),meta:f2_M('ines'),
  text:[t(`伊内丝的条约投资者配偶签证要续期了。休斯敦领事馆要看店里的账：店活着，她才能留下。`,`Inês's treaty-investor spouse visa is up for renewal. The consulate in Houston wants to see the shop's books: as long as the shop is alive, she can stay.`,`O visto de cônjuge de investidor da Inês está para renovar. O consulado em Houston quer ver as contas da loja: enquanto a loja estiver viva, ela pode ficar.`),
   t(`她把一摞收据摔在桌上：“我在里斯本有工作、有名字。在这儿，我是一本账的附件。”`,`She slaps a stack of receipts on the table. "In Lisbon I had a job and a name. Here I'm an attachment to a ledger."`,`Atira um monte de recibos para a mesa. «Em Lisboa tinha emprego e nome. Aqui sou um anexo de um livro de contas.»`)],
  choices:[
   {t:t('一起熬夜把账理清，每一页都签上两个人的名字 · 信任 +2','Stay up together sorting the books, both your names on every page · Trust +2','Ficar acordados a pôr as contas em ordem, os dois nomes em cada página · Confiança +2'),fx:()=>{addTrust('ines',2)}},
   {t:t('让她在店里开一个她自己的鳕鱼饼柜台 · 信任 +1 · 现金 +$100','Give her her own codfish-cake counter in the shop · Trust +1 · Cash +$100','Dar-lhe um balcão só dela de pastéis de bacalhau na loja · Confiança +1 · Dinheiro +100 dólares'),fx:()=>{addTrust('ines',1);S.cash+=100;stat('saud',2)}},
   {t:t('请格蕾丝帮忙准备材料 · 格蕾丝信任 +1','Ask Grace to help with the paperwork · Grace trust +1','Pedir ajuda à Grace com os papéis · Confiança da Grace +1'),fx:()=>{addTrust('grace',1)}}]})
});
f2_home('ines',k=>t(`多年以后，店里墙上挂着两张地图：圣鲁伊斯和阿尔法马。每年六月你们回里斯本过圣安东尼节，${k}在外婆家天台上用两种语言跟鸽子吵架。`,`Years later, two maps hang on the shop wall: San Luís and Alfama. Every June you fly back to Lisbon for Santo António, and ${k} argues with the pigeons on Grandma's rooftop in two languages.`,`Anos depois, há dois mapas na parede da loja: San Luís e Alfama. Todos os junhos voltam a Lisboa para o Santo António, e ${k} discute com os pombos no terraço da avó em duas línguas.`),
 t(`多年以后，店里墙上挂着两张地图：圣鲁伊斯和阿尔法马。伊内丝还是会用里斯本的粗话骂你，骂完把你的碗盛满。`,`Years later, two maps hang on the shop wall: San Luís and Alfama. Inês still swears at you in pure Lisbon, then fills your bowl again.`,`Anos depois, há dois mapas na parede da loja: San Luís e Alfama. A Inês ainda te diz palavrões alfacinhas, e depois volta a encher-te a tigela.`));

/* ---------- ROZ ---------- */
Object.assign(PARTNER.roz,{
 yes:t(`罗兹盯着戒指算了一会儿：“误差范围以内。”她伸出手，“我是工程师，结论只给一次：好。”`,`Roz studies the ring like she's running numbers. "Within tolerance." She holds out her hand. "I'm an engineer. I only give a conclusion once: yes."`,`A Roz estuda o anel como quem faz contas. «Dentro da margem de erro.» Estende a mão. «Sou engenheira. Só dou a conclusão uma vez: sim.»`),
 vow:t(`罗兹说：“我研究了一辈子地底下的东西：哪一层会塌，哪一层撑得住。你是撑得住的那一层。”`,`Roz says, "I've spent my life studying what's underground — which layer caves, which one holds. You're the layer that holds."`,`A Roz diz: «Passei a vida a estudar o que está debaixo da terra — que camada cede, que camada aguenta. Tu és a camada que aguenta.»`),
 baby:t(`罗兹抱孩子的手比在钻台上还稳：“好。新的变量。”然后她哭了，说这个不在任何模型里。`,`Roz's hands are steadier than they ever were on a drilling rig. "Okay. New variable." Then she cries, and says this isn't in any model.`,`As mãos da Roz estão mais firmes do que alguma vez estiveram numa sonda. «Pronto. Variável nova.» Depois chora, e diz que isto não está em modelo nenhum.`),
 moment:()=>({title:t('第一份干净的报告','The first clean report','O primeiro relatório limpo'),meta:f2_M('roz'),
  text:[t(`半夜，罗兹从奥斯汀开车回来，工装都没换，把一张纸拍在你枕头上：罐头厂地块的监测井，第一次验出干净。`,`Midnight. Roz drives in from Austin still in work clothes and slaps a sheet of paper on your pillow: the cannery site's monitoring well has tested clean for the first time.`,`Meia-noite. A Roz chega de Austin ainda com a roupa de trabalho e atira uma folha para a tua almofada: o poço de monitorização da fábrica deu limpo pela primeira vez.`),
   t(`“二十八年，”她说，“我算过了，误差为零。”`,`"Twenty-eight years," she says. "I ran it. Zero error."`,`«Vinte e oito anos», diz. «Fiz as contas. Erro zero.»`)],
  choices:[
   {t:t('开那瓶留着的葡萄酒，就在厨房里喝 · 信任 +2','Open the bottle you\'ve been saving, right there in the kitchen · Trust +2','Abrir a garrafa guardada, ali mesmo na cozinha · Confiança +2'),fx:()=>{addTrust('roz',2);S.cash-=25}},
   {t:t('把报告裱起来，挂在店里若泽的照片旁边 · 口碑 +2','Frame the report and hang it next to José\'s photo in the shop · Reputation +2','Emoldurar o relatório e pendurá-lo ao lado da fotografia do José · Reputação +2'),fx:()=>{S.rep+=2;addTrust('roz',1)}},
   {t:t('连夜开车去雷耶斯牧场，告诉贝托 · 贝托信任 +2','Drive out to the Reyes Ranch tonight and tell Beto · Beto trust +2','Ir já ao rancho dos Reyes contar ao Beto · Confiança do Beto +2'),fx:()=>{addTrust('beto',2);addTrust('roz',1)}}]})
});
f2_home('roz',k=>t(`多年以后，罐头厂旧址成了一片湿地，监测井的铭牌上刻着罗兹的名字。${k}每个周末都去量水位，记录本上的字跟妈妈一样工整。`,`Years later, the old cannery site is wetland, and Roz's name is on the monitoring well's plaque. ${k} goes out every weekend to read the water level, writing it down as neatly as Roz does.`,`Anos depois, o antigo terreno da fábrica é um sapal, e o nome da Roz está na placa do poço de monitorização. ${k} vai lá todos os fins de semana medir o nível da água e aponta com a mesma letra certinha da mãe.`),
 t(`多年以后，罐头厂旧址成了一片湿地，监测井的铭牌上刻着罗兹的名字。她每个周五还是开一个小时车回来，说地底下那几层，她都替你记着。`,`Years later, the old cannery site is wetland, and Roz's name is on the monitoring well's plaque. She still drives an hour home every Friday, and says she's keeping track of every layer under your feet.`,`Anos depois, o antigo terreno da fábrica é um sapal, e o nome da Roz está na placa do poço de monitorização. Ainda faz uma hora de carro todas as sextas, e diz que guarda de cor cada camada debaixo dos teus pés.`));

/* ---------- KYLE ---------- */
Object.assign(PARTNER.kyle,{
 yes:t(`凯尔愣了三秒，抓起吉他：“等等——我得唱着回答。”他弹了四个和弦，唱：“好，好，好。”跑调了。“这是我写过最好的歌。”`,`Kyle freezes for three seconds, then grabs his guitar. "Hang on — I gotta sing this." Four chords. He sings: "Yes, yes, yes." Off-key. "Best song I ever wrote."`,`O Kyle fica parado três segundos e depois agarra na guitarra. «Espera — tenho de responder a cantar.» Quatro acordes. Canta: «Sim, sim, sim.» Desafinado. «A melhor canção que já escrevi.»`),
 vow:t(`凯尔说：“那个我在工具箱最底下锁了十几年的东西，今天当着全镇打开了。搭档——不是乐队的那种——我愿意。”`,`Kyle says, "The thing I kept locked at the bottom of my toolbox for more than ten years — today I opened it in front of the whole town. Partner — not the band kind — I do."`,`O Kyle diz: «Aquilo que guardei fechado no fundo da caixa de ferramentas mais de dez anos — hoje abri-o à frente da vila toda. Parceiro — não o da banda — aceito.»`),
 baby:t(`凯尔不敢接，先在裤子上擦了三遍手。抱住以后，孩子的小手按在他沾着机油的指头上。“看，”他小声说，“签名了。”`,`Kyle won't take the child until he's wiped his hands on his jeans three times. Once he does, a tiny hand closes over his oil-stained finger. "Look," he whispers. "Signed."`,`O Kyle não pega na criança sem antes limpar as mãos às calças três vezes. Quando pega, uma mãozinha fecha-se no dedo dele, sujo de óleo. «Olha», sussurra. «Assinado.»`),
 moment:()=>({title:t('坏掉的拖拉机','A broken tractor','Um trator avariado'),meta:f2_M('kyle'),
  text:[t(`凯尔的父亲开着一台坏拖拉机来了修理铺。镇上有三家修理铺，他偏偏来了这一家。婚礼那天，他没来。`,`Kyle's father drives a broken-down tractor into the repair shop. There are three repair shops in town, and he picked this one. He didn't come to the wedding.`,`O pai do Kyle aparece na oficina com um trator avariado. Há três oficinas na vila, e escolheu esta. Não foi ao casamento.`),
   t(`两个男人对着发动机站了一个钟头，谁都没提那件事。凯尔出来的时候，耳朵是红的。`,`The two of them stand over the engine for an hour. Neither mentions it. When Kyle comes out, his ears are red.`,`Os dois ficam uma hora debruçados sobre o motor. Nenhum fala no assunto. Quando o Kyle sai, tem as orelhas vermelhas.`)],
  choices:[
   {t:t('晚饭多摆一副碗筷，什么也不说 · 信任 +2','Set a third plate at dinner and say nothing · Trust +2','Pôr um terceiro prato ao jantar e não dizer nada · Confiança +2'),fx:()=>{addTrust('kyle',2)}},
   {t:t('给老人送一盘烤肉过去，说是“修理费的零头” · 口碑 +1','Take the old man a plate of brisket — "the change from the repair bill" · Reputation +1','Levar ao velho um prato de carne — «o troco da reparação» · Reputação +1'),fx:()=>{S.rep+=1;addTrust('kyle',1);S.cash-=10}},
   {t:t('[乡愁 40] 在修理铺门口弹那首法多 · 乡愁 +2','[Homesickness 40] Play the fado outside the repair shop · Homesickness +2','[Saudade 40] Tocar o fado à porta da oficina · Saudade +2'),req:()=>S.stats.saud>=40||NEED(t('乡愁 40','Homesickness 40','Saudade 40')),fx:()=>{stat('saud',2);addTrust('kyle',1)}}]})
});
f2_home('kyle',k=>t(`多年以后，孤星法多出了第三张唱片。封面还是店门口的台阶，只是中间多坐了一个${k}，手上也沾着机油。`,`Years later, Lone Star Fado puts out a third record. The cover is still the shop steps — only now ${k} sits between you, with oil on their hands too.`,`Anos depois, os Lone Star Fado lançam o terceiro disco. A capa ainda são os degraus da loja — só que agora ${k} senta-se entre vocês, também com as mãos sujas de óleo.`),
 t(`多年以后，孤星法多出了第三张唱片。凯尔还叫你“搭档”，叫的时候耳朵还是会红。`,`Years later, Lone Star Fado puts out a third record. Kyle still calls you "partner," and his ears still go red when he does.`,`Anos depois, os Lone Star Fado lançam o terceiro disco. O Kyle ainda te chama «parceiro», e ainda fica com as orelhas vermelhas.`));

/* ---------- DELPHINE ---------- */
Object.assign(PARTNER.delphine,{
 yes:t(`德尔菲娜下意识要打分，张开嘴又停住：“不。先问这个问题想说什么。”她看着你，“我知道它想说什么。好。”`,`Delphine starts to give it a score out of habit, then stops. "No. First ask what the question's trying to say." She looks at you. "I know what it's saying. Yes."`,`A Delphine, por hábito, começa a dar nota, e para. «Não. Primeiro pergunta-se o que a pergunta quer dizer.» Olha para ti. «Eu sei o que quer dizer. Sim.»`),
 vow:t(`德尔菲娜说：“我给几千道菜打过分。你从不讨好我，你只做饭，等我坐下。我愿意一辈子不打分，就坐在你的厨房里。”`,`Delphine says, "I've scored thousands of dishes. You never tried to please me. You just cooked, and waited for me to sit down. I'll stop scoring for life, if I can sit in your kitchen."`,`A Delphine diz: «Já dei nota a milhares de pratos. Tu nunca me tentaste agradar. Cozinhavas e esperavas que me sentasse. Deixo de dar notas para sempre, se puder ficar sentada na tua cozinha.»`),
 baby:t(`德尔菲娜没有举相机。她抱着孩子，过了很久才说：“这是我第一次不想拍下来。拍了，就变成别人的故事了。”`,`Delphine doesn't reach for her camera. She holds the child a long time before she speaks. "First time I don't want a picture. Once you take it, it's somebody else's story."`,`A Delphine não pega na máquina. Fica muito tempo com a criança ao colo antes de falar. «É a primeira vez que não quero fotografar. Depois de tirada, passa a ser história de outra pessoa.»`),
 moment:()=>({title:t('电视台来电','The TV call','A chamada da televisão'),meta:f2_M('delphine'),
  text:[t(`一档全国美食节目想来拍若泽烧烤店，还想拍你们家——“夫妻档，镜头会很好看”。`,`A national food show wants to film Zé's — and your home, too. "Husband and wife team, it'll look great on camera."`,`Um programa nacional de culinária quer filmar o Zé's — e a vossa casa também. «Um casal ao balcão, fica ótimo em câmara.»`),
   t(`德尔菲娜把邮件读了两遍，第二遍时问你：“这件事想说什么？”`,`Delphine reads the email twice. The second time through she asks you: "What's this one trying to say?"`,`A Delphine lê o e-mail duas vezes. À segunda pergunta-te: «O que é que isto quer dizer?»`)],
  choices:[
   {t:t('只让他们拍厨房，不拍家 · 信任 +1 · 口碑 +2','Let them film the kitchen, not the house · Trust +1 · Reputation +2','Deixá-los filmar a cozinha, mas não a casa · Confiança +1 · Reputação +2'),fx:()=>{addTrust('delphine',1);S.rep+=2}},
   {t:t('一起回信拒绝，周六晚上照常营业 · 信任 +2','Turn it down together; open Saturday night as usual · Trust +2','Recusar os dois; abrir sábado à noite como sempre · Confiança +2'),fx:()=>{addTrust('delphine',2)}},
   {t:t('全部答应——生意要紧 · 现金 +$200','Say yes to all of it — business is business · Cash +$200','Aceitar tudo — negócio é negócio · Dinheiro +200 dólares'),fx:()=>{S.cash+=200;S.rep+=1;addTrust('delphine',-1)}}]})
});
f2_home('delphine',k=>t(`多年以后，《孤星下的里斯本》出了一本书。最后一页没有照片，只有一行字：“有些东西不需要打分。”书的扉页上，是${k}用蜡笔写的名字。`,`Years later, "Lisbon Under the Lone Star" becomes a book. The last page has no photo, just one line: "Some things don't need a score." On the flyleaf, in crayon, is ${k}'s name.`,`Anos depois, «Lisboa sob a Estrela Solitária» é um livro. A última página não tem fotografia, só uma frase: «Há coisas que não precisam de nota.» Na folha de guarda, a lápis de cera, o nome de ${k}.`),
 t(`多年以后，《孤星下的里斯本》出了一本书。最后一页没有照片，只有一行字：“有些东西不需要打分。”`,`Years later, "Lisbon Under the Lone Star" becomes a book. The last page has no photo, just one line: "Some things don't need a score."`,`Anos depois, «Lisboa sob a Estrela Solitária» é um livro. A última página não tem fotografia, só uma frase: «Há coisas que não precisam de nota.»`));

/* ---------- GRACE ---------- */
Object.assign(PARTNER.grace,{
 yes:t(`格蕾丝按了一下圆珠笔，又按了一下：“作为律师，我应该建议你先签婚前协议。”她把笔放下，“作为我自己——好。”`,`Grace clicks her pen, then clicks it again. "As an attorney, I'd advise a prenup first." She puts the pen down. "As myself — yes."`,`A Grace carrega na esferográfica, e outra vez. «Como advogada, aconselharia primeiro um acordo pré-nupcial.» Pousa a caneta. «Como eu própria — sim.»`),
 vow:t(`格蕾丝说：“我读过的每一份文件都有附加条款。这一份没有。我愿意——无条件，不可撤销。”`,`Grace says, "Every document I've ever read had a rider. This one doesn't. I do — unconditionally and irrevocably."`,`A Grace diz: «Todos os documentos que li tinham uma cláusula adicional. Este não tem. Aceito — sem condições e de forma irrevogável.»`),
 baby:t(`格蕾丝抱着孩子，手里没有笔，也没有文件夹：“你好。我是你妈妈。这句话不需要任何人公证。”`,`Grace holds the child, no pen, no folder. "Hello. I'm your mother. That one doesn't need notarizing."`,`A Grace pega na criança, sem caneta, sem pasta. «Olá. Sou a tua mãe. Isto não precisa de ser reconhecido no notário.»`),
 moment:()=>({title:t('亚速尔老太太的遗嘱','The Azorean widow\'s will','O testamento da viúva açoriana'),meta:f2_M('grace'),
  text:[t(`一位八十多岁的亚速尔老太太来格蕾丝办公室立遗嘱。她的英语只剩几个词，葡语带着岛上的口音。`,`An Azorean widow in her eighties comes to Grace's office to make a will. Her English is down to a few words; her Portuguese has the islands in it.`,`Uma viúva açoriana de oitenta e tal anos vem ao escritório da Grace fazer testamento. Do inglês restam-lhe poucas palavras; o português tem o sotaque das ilhas.`),
   t(`格蕾丝打电话给你：“我需要一个翻译。”停了停，“还需要一个人，在她哭的时候递纸巾。我上一次没递。”`,`Grace calls you. "I need an interpreter." A pause. "And somebody to hand her a tissue if she cries. Last time, I didn't."`,`A Grace liga-te. «Preciso de um intérprete.» Uma pausa. «E de alguém que lhe passe um lenço se ela chorar. Da última vez, não passei.»`)],
  choices:[
   {t:t('去翻译，一个字一个字地，不替她省略 · 信任 +2 · 乡愁 +2','Go and interpret, word for word, leaving nothing out · Trust +2 · Homesickness +2','Ir traduzir, palavra a palavra, sem cortar nada · Confiança +2 · Saudade +2'),fx:()=>{addTrust('grace',2);stat('saud',2)}},
   {t:t('带一盒蛋挞去，先陪她聊聊岛上的事 · 口碑 +2','Bring a box of custard tarts and talk about the islands first · Reputation +2','Levar uma caixa de pastéis de nata e falar primeiro das ilhas · Reputação +2'),fx:()=>{S.rep+=2;S.cash-=15;addTrust('grace',1)}},
   {t:t('请阿尔贝蒂娜太太去，她们讲同一种话 · 阿尔贝蒂娜信任 +2','Send Dona Albertina — they speak the same Portuguese · Albertina trust +2','Mandar a Dona Albertina — falam o mesmo português · Confiança da Albertina +2'),fx:()=>{addTrust('albertina',2)}}]})
});
f2_home('grace',k=>t(`多年以后，格蕾丝夜跑的路线没变，主街跑到教堂再跑回来。只是现在有人骑着自行车在前面领跑——${k}，车筐里放着那支圆珠笔。`,`Years later, Grace's night run hasn't changed: down Main Street to the church and back. Only now someone leads the way on a bike — ${k}, with that ballpoint pen in the basket.`,`Anos depois, a corrida noturna da Grace é a mesma: rua principal até à igreja e de volta. Só que agora há alguém à frente de bicicleta — ${k}, com a esferográfica no cesto.`),
 t(`多年以后，格蕾丝夜跑的路线没变，主街跑到教堂再跑回来。她一边跑一边跟你谈遗嘱以外的一切，谈了这么多年，还没谈完。`,`Years later, Grace's night run hasn't changed: down Main Street to the church and back. She talks with you about everything except wills the whole way, and after all these years, you still haven't run out.`,`Anos depois, a corrida noturna da Grace é a mesma: rua principal até à igreja e de volta. Pelo caminho falam de tudo menos de testamentos, e ao fim destes anos todos ainda não se acabou a conversa.`));

/* ---------- MAYA ---------- */
Object.assign(PARTNER.maya,{
 yes:t(`玛雅把戒指转了一圈：“你知道我从来只签一年的租约。”她看着你，嘴角先动了，“这一份，我签长期的。好。”`,`Maya turns the ring once. "You know I only ever sign one-year leases." She looks at you, and the corner of her mouth goes first. "This one I'm signing long-term. Yes."`,`A Maya roda o anel uma vez. «Sabes que eu só assino contratos de um ano.» Olha para ti, e o canto da boca mexe-se primeiro. «Este assino a longo prazo. Sim.»`),
 vow:t(`玛雅说：“我搬过十一次家，每一次都只租一年。今天我不租了。在你这儿，我买下来。”`,`Maya says, "I've moved eleven times, and every time it was a one-year lease. Today I'm done renting. With you, I'm buying."`,`A Maya diz: «Mudei de casa onze vezes, e foi sempre arrendamento de um ano. Hoje acabou-se o arrendar. Contigo, compro.»`),
 baby:t(`玛雅抱着孩子，笑着嘟囔：“你以后读到博士，就不用闻牛粪了。”然后把脸埋下去，“算了，闻吧。跟我们一起闻。”`,`Maya holds the child and mutters, laughing, "Get yourself a PhD and you'll never have to smell cow manure." Then she buries her face. "Never mind. Smell it. Smell it with us."`,`A Maya pega na criança e resmunga, a rir: «Tira um doutoramento e nunca mais cheiras a estrume.» Depois enterra a cara. «Esquece. Cheira. Cheira connosco.»`),
 moment:()=>({title:t('洗衣店老板来了','The laundromat owners visit','Os donos da lavandaria vêm de visita'),meta:f2_M('maya'),
  text:[t(`玛雅的父母从休斯敦第一次来圣鲁伊斯。她爸进门先摸了一下你的围裙，皱眉：“漂白水放多了。”`,`Maya's parents come up from Houston to San Luís for the first time. Her father walks in and fingers your apron before anything else. A frown. "Too much bleach."`,`Os pais da Maya vêm de Houston a San Luís pela primeira vez. O pai entra e, antes de mais nada, apalpa-te o avental. Franze a testa. «Lixívia a mais.»`),
   t(`她妈把店里转了一圈，小声问玛雅：“你在这儿，是租的还是买的？”`,`Her mother takes a slow lap around the shop and whispers to Maya: "This place — are you renting or did you buy?"`,`A mãe dá uma volta devagar pela loja e pergunta baixinho à Maya: «Aqui, estás a arrendar ou compraste?»`)],
  choices:[
   {t:t('请她爸教你怎么洗围裙 · 信任 +1 · 手艺 +1','Ask her dad to teach you how to wash an apron · Trust +1 · Craft +1','Pedir ao pai dela que te ensine a lavar um avental · Confiança +1 · Ofício +1'),fx:()=>{addTrust('maya',1);stat('oficio',1)}},
   {t:t('替玛雅回答：“买的。” · 信任 +2','Answer for Maya: "Bought." · Trust +2','Responder pela Maya: «Comprado.» · Confiança +2'),fx:()=>{addTrust('maya',2)}},
   {t:t('[$60] 开车带他们去奥斯汀喝八块钱的咖啡 · 魅力 +1','[$60] Drive them to Austin for eight-dollar coffee · Charm +1','[$60] Levá-los a Austin beber café de oito dólares · Charme +1'),req:()=>S.cash>=60||NEED('$60'),fx:()=>{S.cash-=60;stat('charme',1);addTrust('maya',1)}}]})
});
f2_home('maya',k=>t(`多年以后，玛雅的父母搬来圣鲁伊斯，在主街开了一家洗衣店，就在若泽烧烤店对面。${k}放学后在两家店之间跑来跑去，身上一半是炭火味，一半是漂白水味。`,`Years later, Maya's parents move to San Luís and open a laundromat on Main Street, right across from Zé's. After school ${k} runs back and forth between the two, smelling half of charcoal and half of bleach.`,`Anos depois, os pais da Maya mudam-se para San Luís e abrem uma lavandaria na rua principal, mesmo em frente ao Zé's. Depois da escola, ${k} anda de uma loja para a outra, a cheirar metade a carvão e metade a lixívia.`),
 t(`多年以后，玛雅的父母搬来圣鲁伊斯，在主街开了一家洗衣店，就在若泽烧烤店对面。玛雅的房子没有租约，墙上钉满了钉子。`,`Years later, Maya's parents move to San Luís and open a laundromat on Main Street, right across from Zé's. Maya's house has no lease, and its walls are full of nails.`,`Anos depois, os pais da Maya mudam-se para San Luís e abrem uma lavandaria na rua principal, mesmo em frente ao Zé's. A casa da Maya não tem contrato de arrendamento, e as paredes estão cheias de pregos.`));
